mapper.select:
SELECT r.id, r.app_id AS appId, a.name AS appName, a.code AS appCode, r.pipeline_id AS pipelineId, p.name AS pipelineName, r.pipeline_version_no AS pipelineVersionNo, r.branch, r.ref_type AS refType, r.commit_id AS commitId, r.commit_author AS commitAuthor, r.status, r.reused_run_id AS reusedRunId, r.trigger_user_name AS triggerUserName, r.trigger_note AS triggerNote, r.create_time AS createTime, r.started_time AS startedTime, r.finished_time AS finishedTime, r.duration FROM dev_run r INNER JOIN dev_app a ON a.id = r.app_id AND a.is_deleted = 0 INNER JOIN dev_pipeline p ON p.id = r.pipeline_id AND p.is_deleted = 0
r.is_deleted = 0
AND r.pipeline_id = #{query.pipelineId}
AND r.app_id = #{query.appId}
AND r.status = #{query.status}
ORDER BY r.create_time DESC
